340	     * @param lastName  the owner's last name
341	     * @return the 8-character upper-cased hex hash
342	     */
343	    private String identityHash8(String telephone, String lastName) {
344	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
345	        try {
346	            byte[] digest = MessageDigest.getInstance("SHA-256")
347	                .digest(input.getBytes(StandardCharsets.UTF_8));
348	            StringBuilder hex = new StringBuilder(digest.length * 2);
349	            for (byte b : digest) {
350	                hex.append(String.format("%02x", b));
351	            }
352	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
353	        } catch (NoSuchAlgorithmException ex) {
354	            throw new IllegalStateException("SHA-256 not available", ex);
355	        }
