404	    /**
405	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
406	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
407	     * still resemble an existing owner: when it shares an existing owner's {@code soundex(lastName)}
408	     * and postcode while deriving a different identityKey, the owner is flagged with
409	     * {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing owner's id.
410	     * When no such owner exists the flag is set to {@code false} and no match id is recorded. An
411	     * owner with no postcode can never soft-match and is always {@code false}.
412	     *
413	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
414	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
415	     * always flagged {@code false}.
416	     *
417	     * @param owner           the owner being created, with its normalized telephone already applied
418	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
419	     *                        never flagged as a possible duplicate
420	     */
421	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
422	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
423	        if (match != null) {
424	            owner.setPossibleDuplicate(true);
425	            owner.setPossibleDuplicateOf(match.getId());
426	        } else {
427	            owner.setPossibleDuplicate(false);
428	            owner.setPossibleDuplicateOf(null);
429	        }
430	    }
