432	    /**
433	     * Finds the existing owner this owner soft-matches: a different {@link #identityKey(Owner)
434	     * identityKey} but the same {@code soundex(lastName)} and the same postcode. Because the
435	     * telephone now feeds the identityKey, two owners sharing a lastName and postcode with different
436	     * telephones have different keys and so soft-match here rather than being rejected as a hard
437	     * duplicate. When several existing owners match, the one with the lowest id is chosen so the
438	     * result is deterministic. Returns {@code null} when the owner has no postcode or no such
439	     * existing owner exists.
440	     *
441	     * @param owner the owner being created
442	     * @return the matching existing owner, or {@code null} when there is no soft-match
443	     */
444	    private Owner findPossibleDuplicate(Owner owner) {
445	        if (isBlank(owner.getPostcode())) {
446	            return null;
447	        }
448	        String identityKey = identityKey(owner);
449	        String soundex = IdentityKeys.soundex(owner.getLastName());
450	        return this.clinicService.findAllOwners().stream()
451	            .filter(existing -> !identityKey.equals(identityKey(existing))
452	                && soundex.equals(IdentityKeys.soundex(existing.getLastName()))
453	                && owner.getPostcode().equals(existing.getPostcode()))
454	            .min(Comparator.comparing(Owner::getId))
455	            .orElse(null);
456	    }
